local item_lib = require("items")
local function staging(e)
 return e.qglobals.coldainWarPhase=="staging" and e.qglobals.coldainWarStaging=="active"
end

function event_trade(e)
 if e.self:GetNPCTypeID()==118067 and not e.qglobals.coldainWarPhase and item_lib.check_turn_in(e.trade,{item1=1567,item2=30369}) then
  e.self:Emote("breathes deeply and blows into an ornate horn. As the sound echoes through the mountain pass, the local inhabitants scurry to take cover.")
  e.self:Say("I'll be right with you, "..e.other:GetCleanName()..".")
  e.other:SummonItem(30369)
  eq.set_global("coldainWarPhase","staging",3,"F")
  eq.set_global("coldainWarStaging","active",3,"M30")
  eq.signal(2000968,1)
  eq.spawn_condition("greatdivide",0,27,0)
 end
 item_lib.return_items(e.self,e.other,e.trade)
end
